<script setup>
import {computed,onMounted,reactive,ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {ElMessage,ElMessageBox} from 'element-plus';import {getMatch,getMatchResult,submitMatchResult,updateMatchStatus} from '../../api/match';import {useSystemTimeStore} from '../../stores/systemTime'
const route=useRoute(),router=useRouter(),match=ref({}),workflow=ref({submissions:[]}),loading=ref(false),scoreVisible=ref(false),scoreRef=ref(),score=reactive({homeScore:0,awayScore:0}),systemTimeStore=useSystemTimeStore()
const scoreRules={homeScore:[{required:true,type:'number',min:0,message:'比分不得小于0'}],awayScore:[{required:true,type:'number',min:0,message:'比分不得小于0'}]};const actions=computed(()=>({DRAFT:[['PUBLISHED','发布'],['CANCELLED','取消']],PUBLISHED:[['IN_PROGRESS','开始'],['CANCELLED','取消']],IN_PROGRESS:[['CANCELLED','取消']]}[match.value.matchStatus]||[]))
const load=async()=>{loading.value=true;try{match.value=(await getMatch(route.params.id)).data;workflow.value=(await getMatchResult(route.params.id)).data}finally{loading.value=false}};const transition=async(status,label)=>{await ElMessageBox.confirm(`确认${label}该比赛？`,'状态确认');await updateMatchStatus(match.value.matchId,status);systemTimeStore.notifyBusinessChange();await load()};const saveScore=async()=>{await scoreRef.value.validate();await submitMatchResult(match.value.matchId,score);scoreVisible.value=false;ElMessage.success('比分已独立提交，系统将按多人确认规则处理');await load()};onMounted(load)
</script>
<template><el-card v-loading="loading"><template #header><div class="head"><el-page-header @back="router.push('/admin/matches')"><template #content>比赛维护</template></el-page-header><div><el-button type="warning" @click="router.push(`/admin/matches/${match.matchId}/tickets`)">票务配置</el-button><el-button v-for="a in actions" :key="a[0]" :type="a[0]==='CANCELLED'?'danger':'primary'" @click="transition(a[0],a[1])">{{a[1]}}</el-button><el-button v-if="['PUBLISHED','IN_PROGRESS'].includes(match.matchStatus)" type="success" @click="scoreVisible=true">提交我的比分</el-button></div></div></template><div class="fixture"><h2>{{match.homeClubName}}</h2><strong>{{match.homeScore==null?'VS':`${match.homeScore} : ${match.awayScore}`}}</strong><h2>{{match.awayClubName}}</h2></div><el-alert v-if="workflow.reviewStatus" :title="workflow.reviewStatus==='AUTO_PUBLISHED'?'两名管理员比分一致，已自动发布':workflow.reviewReason==='CONFLICT'?'比分存在冲突，等待ADMIN确认':'仅一人提交，等待ADMIN确认'" :type="workflow.reviewStatus==='AUTO_PUBLISHED'?'success':'warning'" :closable="false"/><el-descriptions :column="2" border><el-descriptions-item label="赛季">{{match.seasonName}}</el-descriptions-item><el-descriptions-item label="轮次">{{match.roundName}}</el-descriptions-item><el-descriptions-item label="比赛时间">{{match.matchTime}}</el-descriptions-item><el-descriptions-item label="比赛场馆">{{match.stadiumName}}</el-descriptions-item><el-descriptions-item label="自动开售">{{match.saleStartTime}}</el-descriptions-item><el-descriptions-item label="自动停售">{{match.saleEndTime}}</el-descriptions-item><el-descriptions-item label="状态">{{match.matchStatus}}</el-descriptions-item><el-descriptions-item label="已提交人数">{{workflow.submissions?.length||0}}</el-descriptions-item></el-descriptions></el-card><el-dialog v-model="scoreVisible" title="独立提交比分" width="420px"><el-alert title="提交后不可覆盖；系统需要不同赛事管理员形成共识" type="info" :closable="false"/><el-form ref="scoreRef" :model="score" :rules="scoreRules" label-width="100px" style="margin-top:15px"><el-form-item :label="match.homeClubName" prop="homeScore"><el-input-number v-model="score.homeScore" :min="0"/></el-form-item><el-form-item :label="match.awayClubName" prop="awayScore"><el-input-number v-model="score.awayScore" :min="0"/></el-form-item></el-form><template #footer><el-button @click="scoreVisible=false">取消</el-button><el-button type="primary" @click="saveScore">确认提交</el-button></template></el-dialog></template>
